<?php

namespace App\Http\Controllers;

use App\Models\CoachingInstitute;
use App\Models\InstituteCourse;use App\Models\TutorEducation;use App\Models\InstitutePortfolio;use App\Models\InstituteProfile;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;/** * Coaching centre / private tutor institute profile for the /coaching panel. * * Instant-activation flow: AuthController::register creates the row approved, * so the panel's landing screen is this profile - the basic details entered at * registration - which the owner can keep updated. *   GET  /api/v1/coaching/profile *   PUT  /api/v1/coaching/profile */class CoachingController extends Controller {    use InsightsTrait;    /** GET /coaching/profile - basic details for the panel profile page. */    public function profile(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        return response()->json($this->payload($c));    }    /** PUT /coaching/profile - update the basic details (lenient, any subset). */    public function update(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $d = $r->validate([            'name'=>'sometimes|string|max:200',            'institute_type'=>'sometimes|in:private_coaching,private_institute,private_tutor',            'address'=>'sometimes|nullable|string|max:500',            'country_id'=>'sometimes|nullable|integer|exists:countries,country_id',            'state_id'=>'sometimes|nullable|string|max:32|exists:states,state_subdivision_id',            'district_id'=>'sometimes|nullable|integer|exists:districts,id',            'contact'=>'sometimes|array',            'contact.person_name'=>'sometimes|nullable|string|max:200',            'contact.email'=>'sometimes|nullable|email|max:190',            'contact.phone'=>'sometimes|nullable|string|max:15',        ]);        $data = $c->onboarding ?? [];        if(isset($d['contact'])){            $data['contact'] = array_merge($data['contact'] ?? [], $d['contact']);            unset($d['contact']);        }        $c->update($d + ['onboarding'=>$data]);        return response()->json($this->payload($c));    }    /** Panel payload: the basic details the owner sees/edits on their profile. */    private function payload(CoachingInstitute $c): array {        $onboarding = $c->onboarding ?? [];        $contact = $onboarding['contact'] ?? [];        $labels = $this->locationLabels($c->country_id, $c->state_id, $c->district_id);        return [            'id'=>$c->id,            'institute_code'=>$c->institute_code,            'name'=>$c->name,            'institute_type'=>$c->institute_type,            'address'=>$c->address,            'country_id'=>$c->country_id,            'state_id'=>$c->state_id,            'district_id'=>$c->district_id,            'country_name'=>$labels['country_name'],            'state_name'=>$labels['state_name'],            'district_name'=>$labels['district_name'],            'contact'=>[                'person_name'=>$contact['person_name'] ?? $c->user?->name,                'email'=>$contact['email'] ?? $c->user?->email,                'phone'=>$contact['phone'] ?? $c->user?->whatsapp,            ],            'status'=>$c->onboarding_status,            'submitted_at'=>$c->submitted_at,            'created_at'=>$c->created_at,        ];    }    /** Resolve display names from the real location reference tables. */    private function locationLabels(?int $countryId, ?string $stateId, ?int $districtId): array {        return [            'country_name'=>$countryId ? DB::table('countries')->where('country_id',$countryId)->value('country_name') : null,            'state_name'=>$stateId ? DB::table('states')->where('state_subdivision_id',$stateId)->value('state_subdivision_name') : null,            'district_name'=>$districtId ? DB::table('districts')->where('id',$districtId)->value('district_name') : null,        ];    }    /* -------------------------------------------------------------------     *  Detail tables: courses, tutor education, portfolio (website / PDF)     * ------------------------------------------------------------------- */    /** GET /coaching/details — courses + education + portfolio + institute_profile. */    public function details(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $type = 'coaching'; $id = $c->id;        return response()->json([            'profile' => $c->profile,            'courses' => InstituteCourse::where('institute_type',$type)->where('institute_id',$id)->get(),            'education' => TutorEducation::where('institute_type',$type)->where('institute_id',$id)->get(),            'portfolio' => InstitutePortfolio::where('institute_type',$type)->where('institute_id',$id)->get(),        ]);    }    /** PUT /coaching/details — upsert profile + bulk-replace courses / education / portfolio. */    public function updateDetails(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $d = $r->validate([            'profile'=>'sometimes|array',            'profile.website'=>'sometimes|nullable|string|max:500',            'profile.logo_url'=>'sometimes|nullable|string|max:500',            'profile.banner_url'=>'sometimes|nullable|string|max:500',            'profile.contact_person'=>'sometimes|nullable|string|max:200',            'profile.contact_phone'=>'sometimes|nullable|string|max:20',            'profile.contact_email'=>'sometimes|nullable|email|max:190',            'profile.detailed_address'=>'sometimes|nullable|string|max:1000',            'profile.country_id'=>'sometimes|nullable|integer|exists:countries,country_id',            'profile.state_id'=>'sometimes|nullable|string|max:32|exists:states,state_subdivision_id',            'profile.district_id'=>'sometimes|nullable|integer|exists:districts,id',            'profile.established_year'=>'sometimes|nullable|string|max:10',            'profile.registration_number'=>'sometimes|nullable|string|max:100',            'profile.board_affiliation'=>'sometimes|nullable|string|max:100',            'profile.recognition_status'=>'sometimes|nullable|string|max:50',            'profile.medium_of_instruction'=>'sometimes|nullable|string|max:100',            'profile.student_strength'=>'sometimes|nullable|string|max:20',            'profile.streams'=>'sometimes|nullable|array',            'profile.classes'=>'sometimes|nullable|array',            'courses'=>'sometimes|array',            'courses.*.name'=>'required|string|max:200',            'courses.*.subject'=>'nullable|string|max:100',            'courses.*.level'=>'nullable|string|max:100',            'courses.*.batch'=>'nullable|string|max:100',            'courses.*.duration'=>'nullable|string|max:50',            'courses.*.fee_range'=>'nullable|string|max:100',            'courses.*.description'=>'nullable|string|max:500',            'education'=>'sometimes|array',            'education.*.degree'=>'required|string|max:200',            'education.*.university'=>'nullable|string|max:200',            'education.*.year'=>'nullable|string|max:10',            'education.*.specialization'=>'nullable|string|max:200',            'education.*.description'=>'nullable|string|max:500',            'portfolio'=>'sometimes|array',            'portfolio.*.kind'=>'required|in:website,pdf,image',            'portfolio.*.label'=>'nullable|string|max:200',            'portfolio.*.url'=>'nullable|string|max:500',        ]);        $type = 'coaching'; $id = $c->id;        if(isset($d['profile'])){            $c->profile()->updateOrCreate(                ['institute_type'=>$type,'institute_id'=>$id],                $d['profile']            );        }        if(isset($d['courses'])){            InstituteCourse::where('institute_type',$type)->where('institute_id',$id)->delete();            foreach($d['courses'] as $row)                InstituteCourse::create(['institute_type'=>$type,'institute_id'=>$id,...$row]);        }        if(isset($d['education'])){            TutorEducation::where('institute_type',$type)->where('institute_id',$id)->delete();            foreach($d['education'] as $row)                TutorEducation::create(['institute_type'=>$type,'institute_id'=>$id,...$row]);        }        if(isset($d['portfolio'])){            InstitutePortfolio::where('institute_type',$type)->where('institute_id',$id)->delete();            foreach($d['portfolio'] as $row)                InstitutePortfolio::create(['institute_type'=>$type,'institute_id'=>$id,...$row]);        }        return $this->details($r);    }    /* ------------------------------------------------------------------     *  Granular per-row APIs (add / update / delete one row at a time).     *  Same ownership guard: institute_type='coaching', institute_id=own id.     * ------------------------------------------------------------------ */    /** POST /coaching/courses — add one course row. */    public function courseStore(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $d = $r->validate([            'name'=>'required|string|max:200',            'subject'=>'nullable|string|max:100',            'level'=>'nullable|string|max:100',            'batch'=>'nullable|string|max:100',            'duration'=>'nullable|string|max:50',            'fee_range'=>'nullable|string|max:100',            'description'=>'nullable|string|max:500',        ]);        return response()->json(            InstituteCourse::create(['institute_type'=>'coaching','institute_id'=>$c->id,...$d]), 201);    }    /** PUT /coaching/courses/{id} — update one own course row. */    public function courseUpdate(Request $r, int $id){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $row = InstituteCourse::where('institute_type','coaching')->where('institute_id',$c->id)->find($id);        if(!$row) return response()->json(['message'=>'Course not found'],404);        $row->update($r->validate([            'name'=>'sometimes|required|string|max:200',            'subject'=>'nullable|string|max:100',            'level'=>'nullable|string|max:100',            'batch'=>'nullable|string|max:100',            'duration'=>'nullable|string|max:50',            'fee_range'=>'nullable|string|max:100',            'description'=>'nullable|string|max:500',        ]));        return response()->json($row);    }    /** DELETE /coaching/courses/{id} — delete one own course row. */    public function courseDestroy(Request $r, int $id){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $row = InstituteCourse::where('institute_type','coaching')->where('institute_id',$c->id)->find($id);        if(!$row) return response()->json(['message'=>'Course not found'],404);        $row->delete();        return response()->json(['deleted'=>true]);    }    /** POST /coaching/education — add one tutor-education row. */    public function educationStore(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $d = $r->validate([            'degree'=>'required|string|max:200',            'university'=>'nullable|string|max:200',            'year'=>'nullable|string|max:10',            'specialization'=>'nullable|string|max:200',            'description'=>'nullable|string|max:500',        ]);        return response()->json(            TutorEducation::create(['institute_type'=>'coaching','institute_id'=>$c->id,...$d]), 201);    }    /** PUT /coaching/education/{id} — update one own education row. */    public function educationUpdate(Request $r, int $id){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $row = TutorEducation::where('institute_type','coaching')->where('institute_id',$c->id)->find($id);        if(!$row) return response()->json(['message'=>'Education record not found'],404);        $row->update($r->validate([            'degree'=>'sometimes|required|string|max:200',            'university'=>'nullable|string|max:200',            'year'=>'nullable|string|max:10',            'specialization'=>'nullable|string|max:200',            'description'=>'nullable|string|max:500',        ]));        return response()->json($row);    }    /** DELETE /coaching/education/{id} — delete one own education row. */    public function educationDestroy(Request $r, int $id){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $row = TutorEducation::where('institute_type','coaching')->where('institute_id',$c->id)->find($id);        if(!$row) return response()->json(['message'=>'Education record not found'],404);        $row->delete();        return response()->json(['deleted'=>true]);    }    /** POST /coaching/portfolio — add one portfolio row (website / pdf / image link). */    public function portfolioStore(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $d = $r->validate([            'kind'=>'required|in:website,pdf,image',            'label'=>'nullable|string|max:200',            'url'=>'nullable|string|max:500',        ]);        return response()->json(            InstitutePortfolio::create(['institute_type'=>'coaching','institute_id'=>$c->id,...$d]), 201);    }    /** PUT /coaching/portfolio/{id} — update one own portfolio row. */    public function portfolioUpdate(Request $r, int $id){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $row = InstitutePortfolio::where('institute_type','coaching')->where('institute_id',$c->id)->find($id);        if(!$row) return response()->json(['message'=>'Portfolio item not found'],404);        $row->update($r->validate([            'kind'=>'sometimes|required|in:website,pdf,image',            'label'=>'nullable|string|max:200',            'url'=>'nullable|string|max:500',        ]));        return response()->json($row);    }    /** DELETE /coaching/portfolio/{id} — delete one own portfolio row. */    public function portfolioDestroy(Request $r, int $id){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $row = InstitutePortfolio::where('institute_type','coaching')->where('institute_id',$c->id)->find($id);        if(!$row) return response()->json(['message'=>'Portfolio item not found'],404);        $row->delete();        return response()->json(['deleted'=>true]);    }    /** POST /coaching/portfolio/upload — upload a PDF brochure or image.     *  Stored on the public disk under portfolio/, served via /storage. */    public function portfolioUpload(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $r->validate([            'file'=>'required|file|max:10240|mimes:pdf,jpg,jpeg,png,webp',            'label'=>'nullable|string|max:200',        ]);        $ext = strtolower($r->file('file')->getClientOriginalExtension());        $kind = $ext === 'pdf' ? 'pdf' : 'image';        $path = $r->file('file')->store('portfolio','public');        $row = InstitutePortfolio::create([            'institute_type'=>'coaching','institute_id'=>$c->id,            'kind'=>$kind,'label'=>$r->input('label'),'url'=>'/storage/'.$path,        ]);        return response()->json($row, 201);    }    /** POST /coaching/branding/upload — upload the institute logo or banner.     *  type=logo (square-ish, max 2MB) | banner (wide, max 4MB). The URL is     *  saved straight onto the institute_profiles row so the directory and     *  both panels read it without an extra lookup. */    public function brandingUpload(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        $d = $r->validate([            'type'=>'required|in:logo,banner',            'file'=>'required|image|max:4096',        ]);        $folder = $d['type'] === 'logo' ? 'branding/logos' : 'branding/banners';        $path = $r->file('file')->store($folder,'public');        $url = '/storage/'.$path;        $c->profile()->updateOrCreate(            ['institute_type'=>'coaching','institute_id'=>$c->id],            [$d['type'].'_url'=>$url]        );        return response()->json(['type'=>$d['type'],'url'=>$url], 201);    }    /** DELETE /coaching/branding/{type} — remove the logo or banner. */    public function brandingDestroy(Request $r, string $type){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        if(!in_array($type,['logo','banner'],true))            return response()->json(['message'=>'Unknown branding type'],404);        $c->profile()->updateOrCreate(            ['institute_type'=>'coaching','institute_id'=>$c->id],            [$type.'_url'=>null]        );        return response()->json(['deleted'=>true,'type'=>$type]);    }    /* ------------------------------------------------------------------     *  Insights: search appearances + enquiries + admin messages.     * ------------------------------------------------------------------ */    /** GET /coaching/dashboard — profile + counts + admin messages. */    public function dashboard(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        return response()->json([            'institute'=>$this->payload($c),            'details'=>$this->details($r)->getData(),            ...$this->buildInsightsSummary($r,'coaching',$c->id),        ]);    }

    /** GET /coaching/dashboard-analytics - full analytics payload: overview + calendar + viewers + enquiries. */
    public function dashboardAnalytics(Request $r){
        $c = $r->user()->coachingInstitute;
        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);

        $summary = $this->buildInsightsSummary($r,'coaching',$c->id);

        $totalViews = \App\Models\InstituteView::where('institute_type','coaching')->where('institute_id',$c->id)->count();
        $totalEnquiries = \App\Models\InstituteEnquiry::where('institute_type','coaching')->where('institute_id',$c->id)->count();
        $uniqueStudents = \App\Models\InstituteView::where('institute_type','coaching')->where('institute_id',$c->id)->whereNotNull('student_user_id')->distinct('student_user_id')->count('student_user_id');

        $recentViewers = \App\Models\InstituteView::where('institute_type','coaching')->where('institute_id',$c->id)
            ->leftJoin('users','users.id','=','institute_views.student_user_id')
            ->orderBy('institute_views.created_at','desc')->limit(20)
            ->get([
                'institute_views.id','institute_views.event','institute_views.source',
                'institute_views.country_name','institute_views.state_name','institute_views.district_name',
                'institute_views.filter_q','institute_views.created_at',
                'users.name as student_name',
            ])->map(fn($v)=>[
                'id'=>$v->id,'name'=>$v->student_name ?: 'Unknown','event'=>$v->event,
                'location'=>collect([$v->district_name,$v->state_name,$v->country_name])->filter()->join(', ') ?: null,
                'filter_q'=>$v->filter_q,'source'=>$v->source,'time'=>$v->created_at,
            ]);

        $recentEnquiries = \App\Models\InstituteEnquiry::where('institute_type','coaching')->where('institute_id',$c->id)
            ->leftJoin('users','users.id','=','institute_enquiries.student_user_id')
            ->orderBy('institute_enquiries.created_at','desc')->limit(20)
            ->get([
                'institute_enquiries.id','institute_enquiries.name','institute_enquiries.contact',
                'institute_enquiries.enquiry_for','institute_enquiries.source','institute_enquiries.created_at',
                'users.name as student_name',
            ])->map(fn($e)=>[
                'id'=>$e->id,'name'=>$e->student_user_id ? ($e->name ?: 'Unknown') : ($e->name ?: 'Unknown'),
                'contact'=>$e->contact,'enquiry_for'=>$e->enquiry_for,
                'location'=>collect([$e->district_name,$e->state_name,$e->country_name])->filter()->join(', ') ?: null,
                'source'=>$e->source,'time'=>$e->created_at,
            ]);

        return response()->json([
            'institute'=>$this->payload($c),
            'overview'=>[
                'total_views'=>$totalViews,
                'total_enquiries'=>$totalEnquiries,
                'views_this_month'=>array_sum($summary['days']),
                'enquiries_this_month'=>$summary['enquiries_count'],
                'unique_students'=>$uniqueStudents,
            ],
            'monthly'=>$summary['days'],
            'admin_messages'=>$summary['admin_messages'],
            'recent_viewers'=>$recentViewers,
            'recent_enquiries'=>$recentEnquiries,
        ]);
    }
    /** GET /coaching/insights/summary?month=YYYY-MM */    public function insightsSummary(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        return response()->json($this->buildInsightsSummary($r,'coaching',$c->id));    }    /** GET /coaching/insights/views?date=YYYY-MM-DD */    public function insightsViews(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        return $this->fetchInsightsViews($r,'coaching',$c->id);    }    /** GET /coaching/enquiries */    public function enquiries(Request $r){        $c = $r->user()->coachingInstitute;        if(!$c) return response()->json(['message'=>'No coaching institute profile'],404);        return $this->fetchInsightsEnquiries($r,'coaching',$c->id);    }}